/**
 * The typewriter family. [textReveal] drives the real per-glyph reveal on a text
 * renderer; the fade + Wipe mask are only fallbacks for surfaces that can't do that
 * (curved text, media layers, the native export canvas).
 */
private fun typewriterVisualState(
    progress: Float,
    mode: TextRevealMode,
    durationMs: Long
): LayerAnimationVisualState = LayerAnimationVisualState(
    alphaMultiplier = (0.12f + progress * 0.88f).coerceIn(0f, 1f),
    revealMask = LayerRevealMaskSpec.Wipe(progress = progress),
    textReveal = TextRevealSpec(progress, mode, durationMs)
)

/**
 * Evaluates an Andalusi-ported effect at [progress] (0..1 across its authored length),
 * reading their keyframes directly. Their translations are authored as a fraction of a
 * 700px comp, so they scale to the real layer here.
 */
private fun evaluateAndalusiSpec(
    spec: AndalusiEffectSpec,
    type: LayerAnimationType,
    progress: Float,
    width: Float,
    height: Float
): LayerAnimationVisualState {
    val frame = progress.coerceIn(0f, 1f) * spec.durationFrames
    return LayerAnimationVisualState(
        scaleMultiplier = spec.scale?.valueAt(frame) ?: 1f,
        scaleXMultiplier = spec.scaleX?.valueAt(frame) ?: 1f,
        scaleYMultiplier = spec.scaleY?.valueAt(frame) ?: 1f,
        rotationDeltaDegrees = spec.rotation?.valueAt(frame) ?: 0f,
        translationX = (spec.translateX?.valueAt(frame) ?: 0f) * width,
        translationY = (spec.translateY?.valueAt(frame) ?: 0f) * height,
        alphaMultiplier = (spec.opacity?.valueAt(frame) ?: 1f).coerceIn(0f, 1f),
        revealMask = spec.maskProgress
            ?.valueAt(frame)
            ?.coerceIn(0f, 1f)
            ?.let { andalusiRevealMask(type, it) }
    )
}

